def solve():
    n, m, D = map(int, input().split())
    edges = []
    for _ in range(m):
        v, u = map(int, input().split())
        if v < u:
            edges.append((v, u))
        else:
            edges.append((u, v))
    visited = [False] * (n + 1)
    tree_edges = []
    for edge in edges:
        v, u = edge
        if not visited[v - 1] and not visited[u - 1]:
            visited[v - 1] = True
            visited[u - 1] = True
            tree_edges.append(edge)
    if sum(1 for edge in edges if (edge[0], edge[1]) in [(1, i + 1) for i in range(D)] or (edge[0], edge[1]) in [(i + 1, 1) for i in range(D)]) == D:
        print("YES")
        for edge in tree_edges:
            print(*edge)
    else:
        print("NO")

