def spiralOrder(matrix):
    if not matrix: return []
    R,C = len(matrix),len(matrix[0])
    seen = [[False for _ in range(C)]for _ in range(R)]
    answer = []
    dr,dc = [0,1,-1,0], [1,0,0,-1]
    r,c = 0,0
    for i in range(1,R*C+1):
        answer.append(matrix[r][c])
        seen[r][c] = True
        cr,cc = dr[(i-1)%4],dc[(i-1)%4]
        if 0 <= r+cr < R and 0 <= c+cc < C and not seen[r+cr][c+cc]:
            r,c = r+cr,c+cc
        else:
            cr,cc = dr[(i-2)%4],dc[(i-2)%4]
            if 0 <= r+cr < R and 0 <= c+cc < C and not seen[r+cr][c+cc]:
                r,c = r+cr,c+cc
            else:
                break
    return answer

