def solve(n):
    MOD = 998244353
    dp = [[0] * (n + 1) for _ in range(2)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i + 1):
            if i % 2 == 0:
                dp[i % 2][j] += dp[(i - 1) % 2][j - 1]
            else:
                dp[i % 2][j] += dp[(i - 1) % 2][j + 1]
        for j in range(i + 1):
            dp[i % 2][j] %= MOD
    return dp[n % 2][n // 2]

