from collections import deque, defaultdict

def solve():
    P, R, L = map(int, input().split())
    graph = defaultdict(list)
    for _ in range(L):
        e1, e2 = map(int, input().split())
        if e1 == -2:
            graph[-1].append(e2)
        elif e1 == -1:
            graph[e2].append(-1)
        else:
            graph[e1].append(e2)
    queue = deque([(0, 0)])  # (time, people left to cross)
    visited = set()
    while queue:
        time, people_left = queue.popleft()
        if people_left == P:
            return time
        for boulder in list(graph.keys()):
            if len(graph[boulder]) > 1 and boulder not in visited:
                graph[boulder].pop()
                visited.add(boulder)
                queue.append((time + 1, people_left - 1))
    return P

