    P, R, L = map(int, input().split())
    graph = defaultdict(list)
    for _ in range(L):
        e1, e2 = map(int, input().split())
        graph[e1].append(e2)
        graph[e2].append(e1)

    visited = set()
    queue = deque([(0, 0)])  # (time, people left to cross)
    min_time = float('inf')
    while queue:
        time, people_left = queue.popleft()
        if people_left == P:
            min_time = min(min_time, time)
        for boulder in graph:
            if boulder not in visited and len(graph[boulder]) > 0:
                visited.add(boulder)
                new_people_left = people_left - 1
                for neighbor in graph[boulder]:
                    graph[neighbor].remove(boulder)
                    if len(graph[neighbor]) == 0:
                        graph.pop(neighbor)
                queue.append((time + 1, new_people_left))

    return min_time if min_time != float('inf') else P

