from collections import deque

def calculate_probability():
    N = int(input())
    L = int(input())
    walk = list(map(int, input().split()))
    graph = {}
    for _ in range(N):
        n = int(sys.stdin.readline())
        neighbors = list(map(int, sys.stdin.readline().split()))
        graph[_] = neighbors

    visited = set()
    queue = deque([(0, 1)])  # (node, probability)
    total_probability = 0
    while queue:
        node, probability = queue.popleft()
        if node not in visited:
            visited.add(node)
            if node == L - 1:
                total_probability += probability
            for neighbor in graph[node]:
                if neighbor != walk[node]:
                    queue.append((neighbor, probability / len(graph[node])))

    return total_probability / (2 ** N)


