from collections import defaultdict
import sys

def max_flow(graph, s, t):
    flow = 0
    while True:
        path = bfs(graph, s, t)
        if not path:
            break
        flow += find_path_flow(graph, path, s, t)

    return flow, cost(graph, s, t, flow)

def bfs(graph, s, t):
    visited = [False] * len(graph)
    parent = [-1] * len(graph)
    queue = [s]
    visited[s] = True
    while queue:
        node = queue.pop(0)
        for neighbor in graph[node]:
            if not visited[neighbor] and graph[node][neighbor]['residual'] > 0:
                queue.append(neighbor)
                visited[neighbor] = True
                parent[neighbor] = node
                if neighbor == t:
                    return build_path(parent, s, t)
    return None

def find_path_flow(graph, path, s, t):
    flow = float('inf')
    node = t
    while node != s:
        flow = min(flow, graph[path[node-1]][node]['residual'])
        node = parent[node]
    return flow

def build_path(parent, s, t):
    path = []
    node = t
    while node != s:
        path.append(node)
        node = parent[node]
    path.append(s)
    return path[::-1]

def cost(graph, s, t, flow):
    total_cost = 0
    node = t
    while node != s:
        total_cost += graph[parent[node]][node]['cost'] * flow
        node = parent[node]
    return total_cost

