def solve():
    n, s, t, q = map(int, input().split())
    hills = []
    for _ in range(n):
        x, y, h = map(int, input().split())
        hills.append((x, y, h))
    springs = list(map(int, input().split()))
    towns = list(map(int, input().split()))

    from collections import deque
    visited = [[False]*len(hills) for _ in range(len(hills))]
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    springs_to_towns = {}

    for i in range(s):
        spring_hill = hills[springs[i]-1]
        for j in range(t):
            town_hill = hills[towns[j]-1]
            if not visited[hills.index(town_hill)]:
                queue = deque([(spring_hill, 0)])
                while queue:
                    x, y, h, dist = queue.popleft()
                    if (x, y) == (town_hill[0], town_hill[1]):
                        springs_to_towns[j] = i
                        break
                    for dx, dy in directions:
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < len(hills) and not visited[nx]:
                            new_h = h + abs(nx-x) + abs(ny-y)
                            if new_h <= q:
                                queue.append((hills[nx], ny, new_h, dist+1))
                                visited[nx] = True
                else:
                    return "IMPOSSIBLE"

    total_length = 0
    for i in range(t):
        spring_index = springs_to_towns[i]
        town_index = towns[i]-1
        queue = deque([(hills[spring_index-1], hills[town_index-1], 0)])
        while queue:
            x1, y1, h1, x2, y2, h2, dist = queue.popleft()
            if (x1, y1) == (x2, y2):
                total_length += dist
                break
            for dx, dy in directions:
