    for _ in range(n):
        x, y, h = map(int, input().split())
        hills.append((x, y, h))
    springs = list(map(int, input().split()))
    towns = list(map(int, input().split()))

    from collections import deque
    visited = [[False]*len(hills) for _ in range(len(hills))]
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    springs_to_towns = [[] for _ in range(s+1)]

    for i in range(n):
        for j in range(i+1, n):
            if abs(hills[i][2] - hills[j][2]) > q:
                continue
            dx, dy = abs(hills[i][0]-hills[j][0]), abs(hills[i][1]-hills[j][1])
            if (dx, dy) in directions or (dy, dx) in directions:
                for k in range(s+1):
                    if springs[k] == i and towns[k] == j:
                        springs_to_towns[k].append((i, j))

    total_length = 0
    for i in range(1, t+1):
        queue = deque([(springs[i-1], towns[i-1])])
        visited[springs[i-1]][towns[i-1]] = True
        while queue:
            x, y = queue.popleft()
            if (x, y) == (springs[i-1], towns[i-1]):
                break
            for dx, dy in directions:
                nx, ny = x+dx, y+dy
                if 0 <= nx < len(hills) and 0 <= ny < len(hills) and not visited[nx][ny]:
                    queue.append((nx, ny))
                    visited[nx][ny] = True
        total_length += sum(abs(a-b) for a, b in zip(springs[i-1], towns[i-1]))

