def solve():
    N, M, K = map(int, input().split())
    onions = [list(map(int, input().split())) for _ in range(N)]
    fence_posts = [list(map(int, input().split())) for _ in range(M)]
    onions.sort()
    fence_posts.sort(key=lambda x: (x[1], x[0]))
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        for j in range(1, min(i, K) + 1):
            left = right = 0
            for k in range(M):
                if fence_posts[k][1] <= onions[i - 1][1]:
                    left += 1
                else:
                    break
            for k in range(M - 1, -1, -1):
                if fence_posts[k][1] >= onions[i - 1][1]:
                    right += 1
                else:
                    break
            dp[i][j] = max(dp[i - 1][j], dp[left][j - 1] + (i - left) * (right - left))
    return dp[-1][-1]
